const PROG = 'test6.mjs';
const USAGE = `usage: ${PROG} [-h] --a A --b B --c C --d D`;
const REQUIRED = ['a', 'b', 'c', 'd'];

function printUsage(stream) {
  stream.write(USAGE + '\n');
}

function errorExit(message) {
  printUsage(process.stderr);
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  process.stdout.write(USAGE + '\n');
  process.stdout.write('\n');
  process.stdout.write('options:\n');
  process.stdout.write('  -h, --help  show this help message and exit\n');
  process.stdout.write('  --a A\n');
  process.stdout.write('  --b B\n');
  process.stdout.write('  --c C\n');
  process.stdout.write('  --d D\n');
  process.exit(0);
}

export function parseArgs(argv) {
  const values = {};
  const unrecognized = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp();
    }

    let name = null;
    let inlineValue = null;

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(2, eq);
        inlineValue = token.slice(eq + 1);
      } else {
        name = token.slice(2);
      }
    }

    if (name !== null && REQUIRED.includes(name)) {
      if (inlineValue !== null) {
        values[name] = inlineValue;
        i += 1;
      } else if (i + 1 < argv.length) {
        values[name] = argv[i + 1];
        i += 2;
      } else {
        errorExit(`argument --${name}: expected one argument`);
      }
    } else {
      unrecognized.push(token);
      i += 1;
    }
  }

  if (unrecognized.length > 0) {
    errorExit(`unrecognized arguments: ${unrecognized.join(' ')}`);
  }

  const missing = REQUIRED.filter((n) => !(n in values));
  if (missing.length > 0) {
    errorExit(
      `the following arguments are required: ${missing.map((n) => `--${n}`).join(', ')}`
    );
  }

  return { a: values.a, b: values.b, c: values.c, d: values.d };
}

