// Pure JavaScript HMAC-SHA1 implementation (RFC 2104), block size 64 bytes.

import { sha1 } from './sha1.mjs';

const BLOCK_SIZE = 64;

export function hmacSha1(key, message) {
  let k = key;
  if (k.length > BLOCK_SIZE) {
    k = sha1(k);
  }

  const ipad = new Uint8Array(BLOCK_SIZE);
  const opad = new Uint8Array(BLOCK_SIZE);
  ipad.fill(0x36);
  opad.fill(0x5c);
  for (let i = 0; i < k.length; i++) {
    ipad[i] ^= k[i];
    opad[i] ^= k[i];
  }

  const inner = new Uint8Array(BLOCK_SIZE + message.length);
  inner.set(ipad);
  inner.set(message, BLOCK_SIZE);
  const innerHash = sha1(inner);

  const outer = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outer.set(opad);
  outer.set(innerHash, BLOCK_SIZE);
  return sha1(outer);
}

