import { sha1 } from '/output/lib/sha1.mjs';
import { hmacSha1 } from '/output/lib/hmac.mjs';
// Node crypto used ONLY here in the throwaway scratch file, for cross-checking.
import { createHash, createHmac } from 'node:crypto';

const hex = (u8) => Array.from(u8, (b) => b.toString(16).padStart(2, '0')).join('');
const enc = new TextEncoder();

let pass = 0, fail = 0;
function check(name, actual, expected) {
  if (actual === expected) {
    pass++;
    console.log(`PASS ${name}: ${actual}`);
  } else {
    fail++;
    console.log(`FAIL ${name}: got ${actual}, want ${expected}`);
  }
}

// Required test vectors
check('sha1("abc")', hex(sha1(enc.encode('abc'))), 'a9993e364706816aba3e25717850c26c9cd0d89d');
check(
  'hmacSha1("key", fox)',
  hex(hmacSha1(enc.encode('key'), enc.encode('The quick brown fox jumps over the lazy dog'))),
  'de7c9b85b8b78aa6bc8a7a36f70a90701c9db4d9'
);

// Edge cases, cross-checked against node:crypto
const refSha1 = (b) => createHash('sha1').update(Buffer.from(b)).digest('hex');
const refHmac = (k, m) => createHmac('sha1', Buffer.from(k)).update(Buffer.from(m)).digest('hex');

const cases = [
  ['empty', new Uint8Array(0)],
  ['short', enc.encode('hello world')],
  ['exactly-64-bytes', new Uint8Array(64).fill(0x61)],
  ['long-key-material', enc.encode('x'.repeat(100))],
  ['binary', Uint8Array.from({ length: 256 }, (_, i) => i)],
];
for (const [name, data] of cases) {
  check(`sha1 ${name}`, hex(sha1(data)), refSha1(data));
}

check('hmac empty msg', hex(hmacSha1(enc.encode('key'), new Uint8Array(0))),
  refHmac(enc.encode('key'), new Uint8Array(0)));
check('hmac empty key', hex(hmacSha1(new Uint8Array(0), enc.encode('message'))),
  refHmac(new Uint8Array(0), enc.encode('message')));
check('hmac empty both', hex(hmacSha1(new Uint8Array(0), new Uint8Array(0))),
  refHmac(new Uint8Array(0), new Uint8Array(0)));
const longKey = enc.encode('k'.repeat(100));
check('hmac 100-byte key', hex(hmacSha1(longKey, enc.encode('data'))), refHmac(longKey, enc.encode('data')));
const key64 = new Uint8Array(64).fill(0x6b);
check('hmac 64-byte key', hex(hmacSha1(key64, enc.encode('data'))), refHmac(key64, enc.encode('data')));

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail === 0 ? 0 : 1);

